"""Fix a falsified generated-grid assumption by exact savedEMA-buffer verification."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parent.parent;old=ROOT/'outputs/verify_selection_seed2_actual12_20261011_v3.py';new=ROOT/'outputs/verify_selection_seed2_actual12_20261011_v4.py'
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
folder=ROOT/'outputs/native_selection_collection12_20261011_v2';prior=json.loads((folder/'tensor_reader_protocol.json').read_bytes());assert sha(old)==prior['reader_sha256']
s=old.read_text(encoding='utf8').replace("'tensor_reader_protocol.json'","'tensor_reader_protocol_v4.json'").replace("folder.mkdir(exist_ok=False)","folder.mkdir(exist_ok=True)")
s=s.replace("        reader_report=verify_local.verify(downloads/(name+'.zip'),downloads/(name+'_metadata.json'),folder/'extracted',folder/'packet_verification.json')", "        if (folder/'packet_verification.json').exists():\n            reader_report=read(folder/'packet_verification.json');assert reader_report['status']=='PASS_DOWNLOADED_SELECTION_DIAGNOSTIC_PACKET_HASHES_AND_BINDINGS'\n            assert reader_report['verification_script_sha256']==sha(code/'verify_local.py') and reader_report['collection_protocol_sha256']==sha(code/'protocol.json')\n            assert reader_report['archive_sha256']==sha(downloads/(name+'.zip'))\n            manifest=read(folder/'extracted/packet_manifest.json')\n            for n,item in manifest['files'].items():assert sha(folder/'extracted'/n)==item['sha256'] and (folder/'extracted'/n).stat().st_size==item['bytes']\n        else:reader_report=verify_local.verify(downloads/(name+'.zip'),downloads/(name+'_metadata.json'),folder/'extracted',folder/'packet_verification.json')")
s=s.replace("        error=0.;grid_error=0.;invalid_selected=0", "        audit_root=ROOT/'outputs/native_selection_anchor_audit12_20261011_v2/seed2';audit=read(audit_root/'report.json');case=audit['cases'][arm]\n        assert audit['status']=='PASS_CHECKPOINT_BOUND_EMA_MODEL_AND_NATIVE_GENERATED_ANCHOR_TENSOR_AUDIT' and audit['model_forwards']==audit['training_epochs']==0 and audit['CUDA_initialized'] is False\n        assert case['checkpoint_sha256']==v['checkpoint_sha256']==read(parent/'run/training_completion.json')['last_checkpoint_sha256']\n        assert sha(audit_root/(arm+'.npz'))==case['export_sha256']\n        with np.load(audit_root/(arm+'.npz'),allow_pickle=False) as z:anchor=z['EMA_anchors'].copy();model_anchor=z['model_anchors'].copy();generated=z['generated_anchors'].copy()\n        assert anchor.shape==(8400,4) and anchor.dtype==np.float32 and hashlib.sha256(anchor.tobytes()).hexdigest()==case['array_sha256']\n        assert np.array_equal(model_anchor,generated) and case['model_equal_generated']\n        nominal=[];sizes=[]\n        for h,w in ((80,80),(40,40),(20,20)):\n            yy,xx=np.meshgrid(np.arange(h),np.arange(w),indexing='ij');nominal.append(np.stack([(xx+.5)/w,(yy+.5)/h],-1).reshape(-1,2));sizes.append(np.tile([w,h],(h*w,1)))\n        nominal=np.concatenate(nominal);sizes=np.concatenate(sizes);finite=np.isfinite(anchor).all(1);xy=1/(1+np.exp(-anchor[finite,:2].astype(np.float64)))\n        assert np.array_equal(finite,np.isfinite(generated).all(1)) and np.array_equal(np.floor(xy*sizes[finite]),np.floor(nominal[finite]*sizes[finite]))\n        grid_error=float(np.max(np.abs(xy-nominal[finite])));error=0.;invalid_selected=0")
s=s.replace("_,valid,ids,_,_,_=selection.validate_record(r);grid_error=max(grid_error,selection.verify_grid_centers(r))", "_,valid,ids,_,_,_=selection.validate_record(r);assert np.array_equal(r['dense_anchor_logits'],anchor), 'Observed anchors differ from checkpoint-bound EMA buffer'")
s=s.replace("reader_protocol_sha256=sha(output/'tensor_reader_protocol_v4.json')", "reader_protocol_sha256=sha(output/'tensor_reader_protocol_v4.json'),EMA_anchor_audit_report_sha256=sha(audit_root/'report.json'),all548_observed_anchors_exact_saved_EMA_buffer=True,nominal_feature_cell_assignment_preserved=True,generated_float32_grid_assumption_replaced_by_exact_checkpoint_buffer_binding=True")
s=s.replace("'tensor_verification.json'","'tensor_verification_v4.json'").replace("'seed2_all_three_tensor_verification.json'","'seed2_all_three_tensor_verification_v4.json'")
compile(s,str(new),'exec');new.write_text(s,encoding='utf8',newline='\n')
assert sha(old)==prior['reader_sha256']
spec=dict(prior,reader_sha256=sha(new),repair='Observed EMA anchor buffers have floating point drift; require exact checkpoint-bound arrays for all548 records and preserved nominal feature cells. No relaxed tensor equivalence or model replay.')
for p in (ROOT/'outputs/native_selection_anchor_audit12_20261011_v2/seed2').iterdir():
    if p.is_file():spec['dependencies_sha256'][p.relative_to(ROOT).as_posix()]=sha(p)
(folder/'tensor_reader_protocol_v4.json').write_text(json.dumps(spec,indent=2),encoding='utf8')
(folder/'tensor_verification_failure_v3.json').write_text(json.dumps(dict(status='REJECTED_GENERATED_FLOAT32_GRID_CHECK',reader_sha256=sha(old),reason='Observed native EMA buffer centers differ from generated grid by1.55e-5 despite float32 dtype; old1e-6 tolerance fails. Actual savedEMA arrays and model-vs-generated buffers audited before repair.',model_replay_repeated=False,remote_training_retried=False),indent=2),encoding='utf8')
print('V4 exact EMA buffer reader frozen; v3 source and failure retained')
